mapper.update:
update ai_config
api_key = #{apiKey}, api_base_url = #{apiBaseUrl}, is_default = #{isDefault}, status = #{status}, max_tokens = #{maxTokens}, temperature = #{temperature},
where id = #{id}

mapper.select:
select count(*) from ai_config
where provider = #{provider} and model_name = #{modelName}
and id != #{excludeId}
